/* Auth gate - only meaningful for the manual webhook input
   (schedule-triggered items carry no headers). Also carries `force` through:
   a manual run may ask for the digest outside the local delivery window. */
const input = $input.first().json;
if (input.headers) {
  const provided = String(input.headers.authorization || '').replace(/^Bearer\s+/i, '');
  if (!provided || provided !== $env.CHAT_API_KEY) {
    return [{ json: { __error: true, status: 401, body: { error: { message: 'Invalid API key. Provide it via the Authorization: Bearer header.', type: 'authentication_error', code: 'invalid_api_key' } } } }];
  }
}
return [{ json: { ok: true, force: !!(input.body && input.body.force === true) } }];

/* Build today's agenda - one per recipient, on their own clock.
   Read-only: nothing is mutated here. The only decision is whether a
   recipient's set differs from THEIR last successful push (matched by
   agenda_runs.owner_ref), so an unchanged day stays silent for that person.
   Recipients: the machine owner (owner_ref '', routed to notify's default
   target) plus every active non-owner person in `people`. A person with no
   usable channel is still pushed: notify falls back to the owner and flags
   `degraded`, it never drops silently.
   Timezone: people.tz, resolved through Intl so DST is honoured (Berlin is +1
   in November and +2 in July). "Today", every reminder clock time and the
   delivery window are all local to the recipient - a person on Kiritimati can
   legitimately be one calendar day ahead of the owner. An empty or unusable
   zone falls back to Asia/Shanghai, which is what every digest used before.
   Delivery window: a recipient is only pushed while it is 07:30-16:00 where
   they are, which mirrors the old fixed slots (07:30 primary, 15:30 last
   catch-up) and keeps a 48-ticks-a-day schedule from waking anybody. A manual
   POST admin/agenda/run with {"force":true} ignores the window.
   A: a todo's project rides along as a [label] tag on its line, and the label
   is part of the fingerprint, so re-attributing an item counts as a change.
   Items with no project render exactly as before. */
const H = { 'X-N8N-API-KEY': $env.N8N_API_KEY };
const api = (path, qs) => this.helpers.httpRequest({ method: 'GET', url: 'http://localhost:5678/api/v1' + path, headers: H, qs });
const tables = (await api('/data-tables', { limit: 100 })).data || [];
const idOf = (name) => (tables.find((t) => t.name === name) || {}).id;
const load = async (name, qs) => {
  const id = idOf(name);
  if (!id) return [];
  return (await api('/data-tables/' + id + '/rows', qs)).data || [];
};

if (!idOf('todos') || !idOf('reminders')) {
  throw new Error('todos/reminders data table missing - run n8n/scripts/deploy.mjs first');
}

const [todos, reminders, people, projects, runs] = await Promise.all([
  load('todos', { limit: 250 }),
  load('reminders', { limit: 250 }),
  load('people', { limit: 200 }),
  load('projects', { limit: 200 }),
  load('agenda_runs', { limit: 250 }),
]);

/* ---- per-recipient clock ----
   The window mirrors the old fixed slots: 07:30 was the primary push and 15:30
   the last catch-up, so a digest is delivered between 07:30 and 16:00 local
   and never at midnight. The tick runs every 30 minutes, which is what makes
   "the host was asleep at 07:30" self-healing without a global guard. */
const NOW = new Date();
const DEFAULT_TZ = 'Asia/Shanghai';
const WINDOW_START = '07:30';
const WINDOW_END = '16:00';
const offsetMs = (zone, when) => {
  const dtf = new Intl.DateTimeFormat('en-US', {
    timeZone: zone, hour12: false, year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', second: '2-digit',
  });
  const p = {};
  for (const x of dtf.formatToParts(when)) p[x.type] = x.value;
  /* read the wall clock in that zone, reinterpret it as UTC, take the delta */
  return Date.UTC(Number(p.year), Number(p.month) - 1, Number(p.day), Number(p.hour) % 24, Number(p.minute), Number(p.second))
    - Math.floor(when.getTime() / 1000) * 1000;
};
const clockFor = (tz) => {
  const wanted = String(tz || '').trim();
  let zone = wanted || DEFAULT_TZ;
  let shift;
  try {
    shift = offsetMs(zone, NOW);
  } catch (e) {
    zone = DEFAULT_TZ;
    try { shift = offsetMs(zone, NOW); } catch (e2) { shift = 8 * 3600000; } /* no ICU at all: the pre-tz behaviour */
  }
  const local = new Date(NOW.getTime() + shift);
  const today = local.toISOString().slice(0, 10);
  const localNow = local.toISOString().slice(11, 16);
  return {
    zone,
    tz_invalid: !!wanted && zone !== wanted,
    today,
    localNow,
    inWindow: localNow >= WINDOW_START && localNow <= WINDOW_END,
    endOfToday: Date.parse(today + 'T23:59:59.999Z') - shift,
    localDay: (iso) => {
      const t = Date.parse(iso || '');
      return Number.isFinite(t) ? new Date(t + shift).toISOString().slice(0, 10) : '';
    },
    localTime: (iso) => {
      const t = Date.parse(iso || '');
      return Number.isFinite(t) ? new Date(t + shift).toISOString().slice(11, 16) : '';
    },
    daysLate: (due) => {
      const t = Date.parse(due || '');
      return Number.isFinite(t) ? Math.max(1, Math.round((Date.parse(today) - t) / 86400000)) : 0;
    },
  };
};

/* A manual run with force:true skips the window check only - the once-a-day
   rule below still applies, since that one protects the person, not the clock. */
const force = !!($input.first().json && $input.first().json.force);
const isActive = (p) => p.active === 1 || p.active === true;
const nameOf = (ref) => {
  if (!ref) return '';
  const p = people.find((x) => x.name === ref);
  return p ? (p.display_name || p.name) : ref;
};
/* an unregistered slug still renders (as itself) rather than disappearing */
const projOf = (ref) => {
  if (!ref) return '';
  const p = projects.find((x) => x.name === ref);
  return p ? (p.label || p.name) : ref;
};

const open = todos.filter((t) => t.status === 'open');
const dueReminders = (clk) => reminders.filter((r) => r.status === 'pending' && clk.localDay(r.due_at) && clk.localDay(r.due_at) <= clk.today && Date.parse(r.due_at) <= clk.endOfToday);

/* The owner's three sets, with the same field values a UTC+8 clock produced
   before: an unchanged day must hash to the same fingerprint across this edit,
   otherwise upgrading would re-push everybody once. */
const ownerItems = (clk) => {
  const items = [];
  for (const t of open.filter((x) => !(x.owner_ref || '') && x.due_date && x.due_date <= clk.today)) {
    items.push({ key: 'todo:' + t.id, kind: 'todo', id: t.id, text: String(t.text || '').slice(0, 120), bucket: t.due_date < clk.today ? 'overdue' : 'today', due: t.due_date, days: t.due_date < clk.today ? clk.daysLate(t.due_date) : 0, owner: '', at: '', project: t.project_ref || '', plabel: projOf(t.project_ref) });
  }
  for (const t of open.filter((x) => (x.owner_ref || '') && !(x.ack_at || '') && (!x.due_date || x.due_date <= clk.today))) {
    const late = t.due_date && t.due_date < clk.today;
    items.push({ key: 'wait:' + t.id, kind: 'delegated', id: t.id, text: String(t.text || '').slice(0, 120), bucket: late ? 'overdue' : (t.due_date === clk.today ? 'today' : 'waiting'), due: t.due_date || '', days: late ? clk.daysLate(t.due_date) : 0, owner: nameOf(t.owner_ref), at: '', project: t.project_ref || '', plabel: projOf(t.project_ref) });
  }
  for (const r of dueReminders(clk)) {
    const day = clk.localDay(r.due_at);
    items.push({ key: 'rem:' + r.id, kind: 'reminder', id: r.id, text: String(r.text || '').slice(0, 120), bucket: day < clk.today ? 'overdue' : 'today', due: day, days: day < clk.today ? clk.daysLate(day) : 0, owner: nameOf(r.owner_ref), at: clk.localTime(r.due_at), project: '', plabel: '' });
  }
  return items;
};

/* One member's own agenda: what is assigned to them and needs a move today
   (overdue / due today), plus what they have not acknowledged yet. Items they
   already acked that are not due today are theirs to plan, not ours to nag. */
const memberItems = (name, clk) => {
  const items = [];
  for (const t of open.filter((x) => (x.owner_ref || '') === name)) {
    const due = t.due_date || '';
    if (!((due && due <= clk.today) || !(t.ack_at || ''))) continue;
    const late = due && due < clk.today;
    items.push({ key: 'todo:' + t.id, kind: 'todo', id: t.id, text: String(t.text || '').slice(0, 120), bucket: late ? 'overdue' : (due === clk.today ? 'today' : 'unacked'), due, days: late ? clk.daysLate(due) : 0, owner: '', at: '', project: t.project_ref || '', plabel: projOf(t.project_ref) });
  }
  for (const r of dueReminders(clk).filter((x) => (x.owner_ref || '') === name)) {
    const day = clk.localDay(r.due_at);
    items.push({ key: 'rem:' + r.id, kind: 'reminder', id: r.id, text: String(r.text || '').slice(0, 120), bucket: day < clk.today ? 'overdue' : 'today', due: day, days: day < clk.today ? clk.daysLate(day) : 0, owner: '', at: clk.localTime(r.due_at), project: '', plabel: '' });
  }
  return items;
};

const tag = (i) => (i.plabel ? ' [' + i.plabel + ']' : '');
const line = (i) => {
  if (i.kind === 'reminder') {
    const stamp = i.bucket === 'overdue' ? i.due : i.at;
    return '- ' + (stamp ? stamp + ' ' : '') + i.text + (i.bucket === 'overdue' ? ' (逾期 ' + i.days + ' 天)' : '');
  }
  const who = i.kind === 'delegated' && i.owner ? ' - 等 ' + i.owner : '';
  if (i.bucket === 'overdue') return '- #' + i.id + ' ' + i.text + ' (逾期 ' + i.days + ' 天)' + who;
  return '- #' + i.id + ' ' + i.text + who;
};
const section = (title, rows) => rows.length
  ? String.fromCharCode(10) + title + ' (' + rows.length + ')' + String.fromCharCode(10) + rows.slice(0, 10).map((i) => line(i) + tag(i)).join(String.fromCharCode(10)) + (rows.length > 10 ? String.fromCharCode(10) + '... 还有 ' + (rows.length - 10) + ' 项' : '') + String.fromCharCode(10)
  : '';

const build = (items, who, clk) => {
  const overdue = items.filter((i) => i.bucket === 'overdue').sort((a, b) => b.days - a.days);
  const dueToday = items.filter((i) => i.bucket === 'today').sort((a, b) => String(a.at || '99').localeCompare(String(b.at || '99')));
  const pending = items.filter((i) => i.bucket === 'waiting' || i.bucket === 'unacked');
  const NL = String.fromCharCode(10);
  const message = String(
    clk.today + (who ? ' · ' + who : '') + NL +
    section('逾期', overdue) +
    section('今天到期', dueToday) +
    section(who ? '待确认' : '等待他人', pending) +
    NL + (who
      ? '共 ' + items.length + ' 项 · /ack 确认，/done 完成'
      : '共 ' + items.length + ' 项 · 内容无变化时不会重复推送')
  ).slice(0, 3500);
  const by_project = [];
  for (const i of items) {
    const ref = i.project || '';
    const hit = by_project.find((x) => x.project === ref);
    if (hit) hit.count += 1;
    else by_project.push({ project: ref, label: ref ? projOf(ref) : '未归类', count: 1 });
  }
  by_project.sort((a, b) => b.count - a.count);
  return { message, by_project, counts: { overdue: overdue.length, today: dueToday.length, waiting: pending.length } };
};

/* Rows API caps limit at 250 and rejects raw sortBy values, so sort here.
   Rows written before per-person delivery carry no owner_ref: they belong to
   the owner's history. agenda_date is the recipient's own local date, so it is
   only ever compared against rows with the same owner_ref. */
const refOf = (r) => String(r.owner_ref || '');
const lastOf = (ref) => runs.filter((r) => refOf(r) === ref).slice()
  .sort((a, b) => String(b.createdAt || '').localeCompare(String(a.createdAt || '')))[0] || {};
const sentToday = (ref, today) => runs.some((r) => refOf(r) === ref && String(r.agenda_date || '') === today && Number(r.sent || 0) === 1);
const fpOf = (items) => require('crypto').createHash('sha256')
  .update(JSON.stringify(items.map((i) => [i.key, i.text, i.bucket, i.due, i.at, i.owner, i.plabel]).sort()))
  .digest('hex');

const ownerRow = people.find((p) => isActive(p) && p.role === 'owner');
const members = people
  .filter((p) => isActive(p) && p.role !== 'owner' && String(p.name || ''))
  .slice()
  .sort((a, b) => String(a.name).localeCompare(String(b.name)))
  .map((p) => ({ ref: String(p.name), label: String(p.display_name || p.name), tz: String(p.tz || '') }));
const recipients = [{ ref: '', label: '', tz: ownerRow ? String(ownerRow.tz || '') : '' }].concat(members);

const out = [];
const skipped = [];
for (const rec of recipients) {
  const clk = clockFor(rec.tz);
  /* cheapest test first: at most a third of the zones on earth are inside the
     window at any instant, and this runs 48 times a day */
  if (!clk.inWindow && !force) {
    skipped.push({ recipient: rec.ref || '(default)', reason: 'outside_window', tz: clk.zone, local_time: clk.localNow });
    continue;
  }
  const items = rec.ref ? memberItems(rec.ref, clk) : ownerItems(clk);
  const built = build(items, rec.label, clk);
  const fingerprint = fpOf(items);
  const last_fingerprint = String(lastOf(rec.ref).fingerprint || '');
  const already = sentToday(rec.ref, clk.today);
  const should_send = items.length > 0 && !already && fingerprint !== last_fingerprint;
  if (!should_send) {
    skipped.push({ recipient: rec.ref || '(default)', reason: !items.length ? 'empty' : (already ? 'already_sent_today' : 'unchanged'), item_count: items.length, tz: clk.zone, local_time: clk.localNow });
    continue;
  }
  out.push({ json: {
    ok: true,
    should_send,
    owner: rec.ref,
    recipient: rec.ref || '(default)',
    recipient_name: rec.label || '机主',
    tz: clk.zone,
    tz_invalid: clk.tz_invalid,
    local_time: clk.localNow,
    fingerprint,
    last_fingerprint,
    item_count: items.length,
    counts: built.counts,
    by_project: built.by_project,
    agenda_date: clk.today,
    kind: '今日议程',
    message: built.message,
    preview: built.message.slice(0, 300),
  } });
}

const summary = { recipients_total: recipients.length, pushed: out.length, skipped };
if (!out.length) {
  return [{ json: Object.assign({
    ok: true,
    should_send: false,
    owner: '',
    recipient: '(none)',
    recipient_name: '',
    fingerprint: '',
    last_fingerprint: '',
    item_count: 0,
    counts: { overdue: 0, today: 0, waiting: 0 },
    by_project: [],
    agenda_date: clockFor('').today,
    kind: '今日议程',
    message: '',
    preview: '',
  }, summary) }];
}
return out.map((o) => ({ json: Object.assign({}, o.json, summary) }));

/* Report the failure without pretending the digest was sent: no row is
   written for this recipient, so their next slot (or tomorrow) retries. The
   other recipients are unaffected - the push node continues on error. */
const a = $('Load & Build').item.json;
const d = $json || {};
const e = d.error || {};
return { json: { ok: false, sent: false, recipient: a.recipient, recipient_name: a.recipient_name, tz: a.tz, local_time: a.local_time, reason: String(d.reason || (e.message ? 'delivery_error' : 'delivery_failed')), detail: String(d.detail || e.message || '').slice(0, 180), agenda_date: a.agenda_date, item_count: a.item_count, counts: a.counts, by_project: a.by_project, fingerprint: a.fingerprint, recipients_total: a.recipients_total, skipped: a.skipped } };

/* Persist only what was actually pushed, one row per recipient. A failed
   delivery leaves no row, so that person's next run still compares against
   their own last SUCCESSFUL digest. Runs once per item: with several
   recipients a single row would silence everybody else for the day. Return
   the item itself, not an array - in this mode the array form loses the
   $('Load & Build').item pairing and nothing gets persisted. */
const a = $('Load & Build').item.json;
return { json: { agenda_date: a.agenda_date, fingerprint: a.fingerprint, item_count: a.item_count, sent: 1, preview: a.preview, owner_ref: String(a.owner || '') } };

/* One result per recipient. `degraded` is notify telling us this person had no
   usable channel, so the digest went to the machine owner instead. */
const a = $('Load & Build').item.json;
const d = $json || {};
return { json: { ok: true, sent: true, recipient: a.recipient, recipient_name: a.recipient_name, tz: a.tz, local_time: a.local_time, degraded: !!d.degraded, via: String(d.via || 'default'), agenda_date: a.agenda_date, item_count: a.item_count, counts: a.counts, by_project: a.by_project, fingerprint: a.fingerprint, recipients_total: a.recipients_total, skipped: a.skipped } };
